mapper.select:
SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM quests
WHERE battle_id = #{battleId}
  AND user_id = #{userId}

SELECT DISTINCT quest_template_id
FROM quests
WHERE user_id = #{userId}
  AND quest_template_id IS NOT NULL
  AND created_at >= #{startAt}

SELECT COUNT(1)
FROM quests
WHERE battle_id = #{battleId}

SELECT guild_id
FROM boss_battles
WHERE battle_id = #{battleId}

SELECT role
FROM guild_members
WHERE guild_id = #{guildId}
  AND user_id = #{userId}
  AND left_at IS NULL
LIMIT 1

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM quest_verifications
WHERE quest_id = #{questId}

SELECT COUNT(1)
FROM diets
WHERE user_id = #{userId}
  AND eaten_at >= #{startAt}
  AND eaten_at < #{endAt}

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM diets
WHERE user_id = #{userId}
  AND eaten_at >= #{startAt}
  AND eaten_at < #{endAt}
  AND meal_type = #{mealType}

SELECT COUNT(1)
FROM (
    SELECT dns.user_id, dns.summary_date
    FROM daily_nutrition_summaries dns
    JOIN guild_members gm ON gm.user_id = dns.user_id
    JOIN users u ON u.user_id = gm.user_id
    WHERE gm.guild_id = #{guildId}
      AND gm.left_at IS NULL
      AND u.status = 'ACTIVE'
      AND dns.summary_date BETWEEN #{startDate} AND #{endDate}
      AND dns.total_sugar_g <= #{thresholdValue}
    GROUP BY dns.user_id, dns.summary_date
) counted

SELECT COUNT(1) FROM ( SELECT bp.user_id, CAST(d.eaten_at AS DATE) AS activity_date, SUM( CASE #{metricType} WHEN 'CALORIE' THEN d.total_calories WHEN 'PROTEIN' THEN d.total_protein_g WHEN 'CARBOHYDRATE' THEN d.total_carbs_g WHEN 'FAT' THEN d.total_fat_g WHEN 'SUGAR' THEN d.total_sugar_g WHEN 'SODIUM' THEN d.total_sodium_mg WHEN 'FIBER' THEN d.total_fiber_g WHEN 'IRON' THEN d.total_iron_mg WHEN 'PHOSPHORUS' THEN d.total_phosphorus_mg WHEN 'POTASSIUM' THEN d.total_potassium_mg WHEN 'VITAMIN_A' THEN d.total_vitamin_a_ug_rae WHEN 'BETA_CAROTENE' THEN d.total_beta_carotene_ug WHEN 'RETINOL' THEN d.total_retinol_ug ELSE 0 END ) AS metric_value FROM boss_battle_participants bp JOIN diets d ON d.user_id = bp.user_id WHERE bp.battle_id = #{battleId} AND CAST(d.eaten_at AS DATE) BETWEEN #{startDate} AND #{endDate} AND CAST(d.eaten_at AS DATE) >= CAST(bp.joined_at AS DATE) AND (bp.left_at IS NULL OR CAST(d.eaten_at AS DATE) < CAST(bp.left_at AS DATE)) GROUP BY bp.user_id, CAST(d.eaten_at AS DATE) HAVING
metric_value >= #{thresholdValue}
metric_value <= #{thresholdValue}
metric_value BETWEEN #{thresholdMinValue} AND #{thresholdMaxValue}
metric_value > 0
metric_value <= 0
1 = 0
) counted

SELECT COUNT(1) FROM boss_battle_participants bp JOIN diets d ON d.user_id = bp.user_id WHERE bp.battle_id = #{battleId} AND CAST(d.eaten_at AS DATE) BETWEEN #{startDate} AND #{endDate} AND CAST(d.eaten_at AS DATE) >= CAST(bp.joined_at AS DATE) AND (bp.left_at IS NULL OR CAST(d.eaten_at AS DATE) < CAST(bp.left_at AS DATE)) AND CASE #{metricType} WHEN 'CALORIE' THEN d.total_calories WHEN 'PROTEIN' THEN d.total_protein_g WHEN 'CARBOHYDRATE' THEN d.total_carbs_g WHEN 'FAT' THEN d.total_fat_g WHEN 'SUGAR' THEN d.total_sugar_g WHEN 'SODIUM' THEN d.total_sodium_mg WHEN 'FIBER' THEN d.total_fiber_g WHEN 'IRON' THEN d.total_iron_mg WHEN 'PHOSPHORUS' THEN d.total_phosphorus_mg WHEN 'POTASSIUM' THEN d.total_potassium_mg WHEN 'VITAMIN_A' THEN d.total_vitamin_a_ug_rae WHEN 'BETA_CAROTENE' THEN d.total_beta_carotene_ug WHEN 'RETINOL' THEN d.total_retinol_ug ELSE NULL END
>= #{thresholdValue}
<= #{thresholdValue}
BETWEEN #{thresholdMinValue} AND #{thresholdMaxValue}
> 0
<= 0
IS NULL AND 1 = 0

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM reward_claims
WHERE user_id = #{userId}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
